import{_ as a,c as t,o as s,ag as o}from"./chunks/framework.DWdSXOaE.js";const g=JSON.parse('{"title":"Typography","description":"","frontmatter":{},"headers":[],"relativePath":"design-standards/typography.md","filePath":"design-standards/typography.md"}'),i={name:"design-standards/typography.md"};function r(n,e,l,d,h,p){return s(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="typography" tabindex="-1">Typography <a class="header-anchor" href="#typography" aria-label="Permalink to &quot;Typography&quot;">​</a></h1><p>The Fluxive Blueprint Theme exclusively uses the <strong>Inter</strong> font family. Inter is a variable font designed specifically for user interfaces, offering excellent legibility at small sizes and clean, modern aesthetics at display sizes.</p><h2 id="font-family" tabindex="-1">Font Family <a class="header-anchor" href="#font-family" aria-label="Permalink to &quot;Font Family&quot;">​</a></h2><div class="language-css vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">font-family</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: &#39;Inter&#39;, </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">sans-serif</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><h2 id="weights" tabindex="-1">Weights <a class="header-anchor" href="#weights" aria-label="Permalink to &quot;Weights&quot;">​</a></h2><p>We primarily use four weights to establish hierarchy:</p><ul><li><strong>Regular (400)</strong>: Used for body text and long-form content.</li><li><strong>Medium (500)</strong>: Used for navigation links, button text, and subtle emphasis.</li><li><strong>SemiBold (600)</strong>: Used for subheadings (<code>h3</code>, <code>h4</code>) and important data points.</li><li><strong>Bold (700)</strong>: Used for major headings (<code>h1</code>, <code>h2</code>) to create strong visual anchors.</li></ul><h2 id="type-scale" tabindex="-1">Type Scale <a class="header-anchor" href="#type-scale" aria-label="Permalink to &quot;Type Scale&quot;">​</a></h2><p>We follow a standard fluid type scale.</p><h3 id="headings" tabindex="-1">Headings <a class="header-anchor" href="#headings" aria-label="Permalink to &quot;Headings&quot;">​</a></h3><ul><li><strong>H1</strong>: Large, bold, tracking-tight. Used for page titles.</li><li><strong>H2</strong>: Significant section dividers. Bottom border often applied.</li><li><strong>H3</strong>: Subsection headers.</li></ul><h3 id="body" tabindex="-1">Body <a class="header-anchor" href="#body" aria-label="Permalink to &quot;Body&quot;">​</a></h3><ul><li><strong>Base</strong>: <code>16px</code> (1rem). The standard reading size.</li><li><strong>Small</strong>: <code>14px</code> (0.875rem). Used for sidebars, metadata, and dense data tables.</li></ul><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><blockquote><p><strong>The quick brown fox jumps over the lazy dog.</strong></p><p><em>The quick brown fox jumps over the lazy dog.</em></p><p><code>The quick brown fox jumps over the lazy dog.</code> (Monospace: usually Fira Code or system mono)</p></blockquote>',15)])])}const u=a(i,[["render",r]]);export{g as __pageData,u as default};
